// src/tools/openPage.ts
async function openPage(options) {
  const session = getSession();
  const page = await session.getPage();
  const viewport = options.viewport ?? { width: 1280, height: 800 };
  await page.setViewportSize(viewport);
  const consoleMessages = [];
  const failedRequests = [];
  page.removeAllListeners("console");
  page.removeAllListeners("requestfailed");
  page.removeAllListeners("response");
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") {
      consoleMessages.push({ type: msg.type(), text: msg.text() });
    }
  });
  page.on("requestfailed", (req) => {
    failedRequests.push({ url: req.url(), status: null, errorText: req.failure()?.errorText });
  });
  page.on("response", (res) => {
    if (res.status() >= 400) {
      failedRequests.push({ url: res.url(), status: res.status() });
    }
  });
  try {
    await page.goto(options.url, { waitUntil: "load" });
  } catch (error2) {
    const message = error2 instanceof Error ? error2.message : String(error2);
    throw new Error(`Eyes: navigation to ${options.url} failed: ${message}`);
  }
  const screenshotBuffer = await page.screenshot();
  const [a11yIssues, visualIssues, interactiveElements] = await Promise.all([
    runA11yAudit(page),
    collectVisualIssues(page),
    collectInteractiveElements(page)
  ]);
  return {
    url: page.url(),
    screenshotBase64: screenshotBuffer.toString("base64"),
    consoleMessages,
    failedRequests,
    a11yIssues,
    visualIssues,
    interactiveElements
  };
}
async function collectInteractiveElements(page) {
  return page.$$eval(
    "a, button, input, select, textarea",
    (elements) => elements.slice(0, 50).map((el, i) => {
      el.setAttribute("data-eyes-id", String(i));
      const tagName = el.tagName.toLowerCase();
      const text = (el.textContent || el.value || "").trim().slice(0, 80);
      const href = el.getAttribute("href") ?? void 0;
      return { selector: `[data-eyes-id="${i}"]`, tagName, text, href };
    })
  );
}

// src/tools/screenshot.ts
async function takeScreenshot(options) {
  const session = getSession();
  const page = await session.getPage();
  await page.setViewportSize(options.viewport);
  const buffer = await page.screenshot();
  return { screenshotBase64: buffer.toString("base64") };
}

